// Modules generated by the integration (src/index.ts).

declare module "virtual:publisher/templates" {
  type Component = (props: Record<string, unknown>) => unknown;
  export const Layout: Component;
  export const templates: Record<string, Component>;
}

declare module "virtual:publisher/site" {
  import type { CodedPageInfo, SiteInfo } from "@publisher/client";
  /** The site as it was when the site was built. */
  export const site: SiteInfo;
  export const pages: CodedPageInfo[];
}

// For `tsc` alone (the package typecheck): .astro files are checked by `astro check` in the demo.
declare module "*.astro" {
  const Component: (props: Record<string, unknown>) => unknown;
  export default Component;
}
